/** 📖 Which brand SVG to render when the canonical id is desktop-only.
 *  Desktop ids like `claude-app` reuse their chainable cousin's SVG (Claude
 *  brand = same logo, just framed with a dashed ring for the "non chainable"
 *  tooltip). Without this map, the renderer would fall back to a generic
 *  initial for these desktop entries. */
const DESKTOP_SVG_FALLBACK: Record<string, string> = {
  "claude-app": "claude",
  "codex-app": "codex",
  "vscode-copilot": "copilot",
};

/** 📖 Branded logo for a known agent id. Renders the glyph in its brand color. */
/**
 * 📖 Branded logo for a known agent id. Renders the glyph in its brand color.
 * When `kind === "desktop"`, wraps it in a dashed ring + sets a tooltip so the
 * user immediately sees "this one isn't chainable from kandown". The SVG is
 * resolved through DESKTOP_SVG_FALLBACK for desktop ids that reuse a chainable
 * brand (e.g. `claude-app` → Claude SVG, ringed + tooltip'd).
 */
export function AgentGlyph({
  id,
  size = 16,
  className,
  kind = 'chainable',
}: {
  id: string;
  size?: number;
  className?: string;
  kind?: 'chainable' | 'desktop';
}) {
  const data = AGENT_GLYPHS[id] || AGENT_GLYPHS[DESKTOP_SVG_FALLBACK[id]];
  if (!data) return null;
  const isDesktop = kind === 'desktop';
  const { t } = useTranslation();
  const tooltip = isDesktop
    ? t('agent.desktopTooltip', { name: displayNameFor(id, isDesktop) })
    : undefined;
  const svg = (
    <svg
      viewBox={data.viewBox}
      width={size}
      height={size}
      fill="currentColor"
      style={{ color: data.color, flex: 'none', display: 'block' }}
      className={className}
      aria-hidden="true"
      dangerouslySetInnerHTML={{ __html: data.inner }}
    />
  );
  if (!isDesktop) return svg;
  return (
    <span
      className="inline-flex items-center justify-center rounded-full border border-dashed border-fg-muted/60 p-px"
      style={{ width: size + 4, height: size + 4 }}
      title={tooltip}
      aria-label={tooltip}
    >
      {svg}
    </span>
  );
}

/** 📖 Saturated palette used to give every human assignee a stable, distinct
 *  color (deterministic hash → palette index). All colours are Tailwind 500s
 *  that hold white text contrast on both light and dark themes. */
const HUMAN_PALETTE = [
  '#EF4444', // red     500
  '#F97316', // orange  500
  '#F59E0B', // amber   500
  '#84CC16', // lime    500
  '#10B981', // emerald 500
  '#06B6D4', // cyan    500
  '#3B82F6', // blue    500
  '#8B5CF6', // violet  500
  '#D946EF', // fuchsia 500
  '#EC4899', // pink    500
] as const;

/** 📖 djb2-flavour hash → palette index. Same name = same color across reloads
 *  and across the team, so vava always shows up in the same slot. */
function hashColor(name: string): string {
  let h = 5381;
  for (let i = 0; i < name.length; i++) h = ((h << 5) + h + name.charCodeAt(i)) | 0;
  return HUMAN_PALETTE[Math.abs(h) % HUMAN_PALETTE.length];
}

/** 📖 Human fallback avatar: a vibrant solid disc with the assignee's initial
 *  in white, an inset white ring for separation from the row, and a soft
 *  shadow for depth. Visually unmistakable vs. the small monochrome brand
 *  glyphs used for chainable + desktop agents — a Linear-style "person"
 *  signal that says "this person, not an AI". */
function HumanAvatar({ name, size = 16 }: { name: string; size?: number }) {
  const letter = (name.trim().charAt(0) || '?').toUpperCase();
  return (
    <span
      className="inline-flex items-center justify-center rounded-full font-semibold text-white shadow-sm ring-1 ring-inset ring-white/40"
      style={{
        width: size + 4,
        height: size + 4,
        backgroundColor: hashColor(name),
        fontSize: Math.max(9, Math.round(size * 0.62)),
      }}
      aria-hidden="true"
    >
      {letter}
    </span>
  );
}

/** 📖 Renders the canonical display name for an id, with an optional "(app)"
 *  suffix in desktop mode so the label distinguishes Claude from Claude app. */
function displayNameFor(id: string, isDesktop: boolean): string {
  const base = AGENT_DISPLAY[id] ?? id;
  return isDesktop && !/\(app\)|desktop/i.test(base) ? base + ' (app)' : base;
}

/**
 * 📖 The one component rows/cards should use. Given an assignee string it shows
 * the branded agent logo when it matches a known agent, otherwise a human
 * avatar (the assignee's initial). Optional `title` override for tooltips.
 */
/**
 * 📖 The one component rows/cards should use. Resolves the assignee through
 * `matchAgent` (which honours the `desktop:` prefix) and renders either the
 * branded logo or a human fallback avatar. Desktop-rendered entries carry a
 * dashed ring + tooltip so the user knows the task is label-only and cannot
 * be launched from kandown.
 */
export function AssigneeAvatar({
  assignee,
  size = 16,
  withLabel = false,
}: {
  assignee: string | null | undefined;
  size?: number;
  withLabel?: boolean;
}) {
  const match = useMemo(() => matchAgent(assignee), [assignee]);
  if (!assignee) return null;
  return (
    <span className="inline-flex items-center gap-1 min-w-0" title={assignee}>
      {match ? (
        <AgentGlyph id={match.id} size={size} kind={match.kind} />
      ) : (
        <HumanAvatar name={assignee} size={size} />
      )}
      {withLabel && (
        <span className="truncate text-fg-muted">{match ? displayNameFor(match.id, match.kind === 'desktop') : assignee}</span>
      )}
    </span>
  );
}
